/* Generated by `helix family machines` from machine.ts beside it. Do not
   edit: change the machine and run it again. */
import { type ParallelContext, type ParallelInput, counted, ready } from './machine.js'

export type { ParallelContext, ParallelInput } from './machine.js'

/** The name machine.ts exports the machine as. */
export const NAME = 'parallel'

/** The state `dropping(gliding, drawing)`. */
export const STATE_DROPPING__GLIDING__DRAWING = 0
/** The state `dropping(gliding, drawn)`. */
export const STATE_DROPPING__GLIDING__DRAWN = 1
/** The state `dropping(landed, drawing)`. */
export const STATE_DROPPING__LANDED__DRAWING = 2
/** The state `dropping(landed, drawn)`. */
export const STATE_DROPPING__LANDED__DRAWN = 3
/** The state `idle`. */
export const STATE_IDLE = 4
/** Each state's name, by its number. */
export const STATES = ['dropping(gliding, drawing)', 'dropping(gliding, drawn)', 'dropping(landed, drawing)', 'dropping(landed, drawn)', 'idle'] as const

/** Each state as the machine writes it, by the number a deadline names its owner by. */
export const NODES = ['dropping', 'gliding', 'landed', 'drawing', 'drawn', 'idle'] as const

/** The event `DROP`. */
export const EVENT_DROP = 0
/** The event `LANDED`. */
export const EVENT_LANDED = 1
/** The event `DRAWN`. */
export const EVENT_DRAWN = 2
/** The event `ABORT`. */
export const EVENT_ABORT = 3
/** The event `SKIP`. */
export const EVENT_SKIP = 4
/** Each event's name, by its number. */
export const EVENTS = ['DROP', 'LANDED', 'DRAWN', 'ABORT', 'SKIP'] as const

/** The effect `draw`. */
export const EFFECT_DRAW = 0
/** The effect `land`. */
export const EFFECT_LAND = 1
/** The effect `settle`. */
export const EFFECT_SETTLE = 2
/** The effect `deadline`. */
export const EFFECT_DEADLINE = 3
/** The effect `deadline-end`. */
export const EFFECT_DEADLINE_END = 4
/** Each effect's name, by its number. */
export const EFFECTS = ['draw', 'land', 'settle', 'deadline', 'deadline-end'] as const

/** Each request event's name, by its number. */
export const ASKS = [] as const

/** A literal an effect is given. */
export type Argument = Readonly<Record<string, boolean | number | string>>

/** An effect the host performs: its number, and its argument where it has one. */
export type Effect = readonly [effect: number, argument?: Argument]

/** A move: the state it leaves the machine in, the context after it, and the effects it runs, in order. */
export interface Move {
  readonly context: ParallelContext
  readonly effects: readonly Effect[]
  readonly state: number
}

/** A request: the events the host asks with first, in order, and the move for each outcome. */
export interface Asking {
  readonly accept: Move
  readonly ask: readonly number[]
  readonly refuse: Move
}

/** The state the machine is in, read from its context. */
export const start = (_context: ParallelContext): number =>
  STATE_IDLE

/** The effects of starting in a state, as a host that mounts the machine runs them. */
export const entering = (state: number): readonly Effect[] => {
  switch (state) {
    case STATE_DROPPING__GLIDING__DRAWING:
      return [[EFFECT_LAND], [EFFECT_DRAW], [EFFECT_DEADLINE, { ms: 1000, owner: 3 }]]
    case STATE_DROPPING__GLIDING__DRAWN:
      return [[EFFECT_LAND]]
    case STATE_DROPPING__LANDED__DRAWING:
      return [[EFFECT_DRAW], [EFFECT_DEADLINE, { ms: 1000, owner: 3 }]]
  }
  return []
}

/** What `dropping(gliding, drawing)` does with each event. */
const inDroppingGlidingDrawing = (context: ParallelContext, event: number, input: ParallelInput): Move | Asking | undefined => {
  switch (event) {
    case EVENT_LANDED:
      return { context: context, effects: [], state: STATE_DROPPING__LANDED__DRAWING }
    case EVENT_DRAWN:
      return ready(context, input) ? { context: context, effects: [[EFFECT_DEADLINE_END, { owner: 3 }]], state: STATE_DROPPING__GLIDING__DRAWN } : undefined
    case EVENT_ABORT:
      return { context: context, effects: [[EFFECT_DEADLINE_END, { owner: 3 }]], state: STATE_IDLE }
  }
  return undefined
}

/** What `dropping(gliding, drawn)` does with each event. */
const inDroppingGlidingDrawn = (context: ParallelContext, event: number, _input: ParallelInput): Move | Asking | undefined => {
  switch (event) {
    case EVENT_LANDED:
      return { context: counted(context), effects: [[EFFECT_SETTLE]], state: STATE_IDLE }
  }
  return undefined
}

/** What `dropping(landed, drawing)` does with each event. */
const inDroppingLandedDrawing = (context: ParallelContext, event: number, input: ParallelInput): Move | Asking | undefined => {
  switch (event) {
    case EVENT_DRAWN:
      return ready(context, input) ? { context: counted(context), effects: [[EFFECT_DEADLINE_END, { owner: 3 }], [EFFECT_SETTLE]], state: STATE_IDLE } : undefined
    case EVENT_ABORT:
      return { context: context, effects: [[EFFECT_DEADLINE_END, { owner: 3 }]], state: STATE_IDLE }
  }
  return undefined
}

/** What `idle` does with each event. */
const inIdle = (context: ParallelContext, event: number, _input: ParallelInput): Move | Asking | undefined => {
  switch (event) {
    case EVENT_DROP:
      return { context: context, effects: [[EFFECT_LAND], [EFFECT_DRAW], [EFFECT_DEADLINE, { ms: 1000, owner: 3 }]], state: STATE_DROPPING__GLIDING__DRAWING }
    case EVENT_SKIP:
      return { context: context, effects: [[EFFECT_DRAW], [EFFECT_DEADLINE, { ms: 1000, owner: 3 }]], state: STATE_DROPPING__LANDED__DRAWING }
  }
  return undefined
}

/**
 * What an event does in a state: a move, a request, or `undefined` where the
 * state ignores it.
 */
export const step = (state: number, context: ParallelContext, event: number, input: ParallelInput): Move | Asking | undefined => {
  switch (state) {
    case STATE_DROPPING__GLIDING__DRAWING:
      return inDroppingGlidingDrawing(context, event, input)
    case STATE_DROPPING__GLIDING__DRAWN:
      return inDroppingGlidingDrawn(context, event, input)
    case STATE_DROPPING__LANDED__DRAWING:
      return inDroppingLandedDrawing(context, event, input)
    case STATE_IDLE:
      return inIdle(context, event, input)
  }
  return undefined
}

/**
 * The move a state's deadline makes when it ends, or `undefined` where the
 * state `owner` names is not active in `state`.
 */
export const expire = (state: number, context: ParallelContext, owner: number): Move | undefined => {
  switch (state) {
    case STATE_DROPPING__GLIDING__DRAWING:
      return owner === 3 ? { context: context, effects: [[EFFECT_DEADLINE_END, { owner: 3 }]], state: STATE_DROPPING__GLIDING__DRAWN } : undefined
    case STATE_DROPPING__LANDED__DRAWING:
      return owner === 3 ? { context: counted(context), effects: [[EFFECT_DEADLINE_END, { owner: 3 }], [EFFECT_SETTLE]], state: STATE_IDLE } : undefined
  }
  return undefined
}

/** The move the machine's cancel makes from a state, where it has one. */
export const cancel = (_state: number, _context: ParallelContext): Move | undefined => undefined

/** The custom states a host records while the machine is in `state`. */
export const mark = (_state: number): readonly string[] => []
